css:
:root{--bg:#fbfaf7;--pane:#fff;--sunk:#f3f0e9;--ink:#171614;--ink2:#4a463e;--mut:#7d7768;
 --line:#e4dfd3;--line2:#cec7b7;--amber:#b5780a;--stop:#a83226;--ok:#2c6b50;--blue:#2b5fa8}
@media(prefers-color-scheme:dark){:root:not([data-theme=light]){
 --bg:#141310;--pane:#1c1b16;--sunk:#232119;--ink:#f3f0e8;--ink2:#c4bfb2;--mut:#8e8877;
 --line:#302d24;--line2:#413d31;--amber:#f0b53c;--stop:#e8897c;--ok:#7cc4a2;--blue:#8ab4f0}}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 Inter,system-ui,sans-serif}
.page{max-width:1120px;margin:0 auto;padding:0 26px 90px}
h1,h2,h3{font-family:Sora,system-ui,sans-serif;line-height:1.18;margin:0;letter-spacing:-.02em}
h1{font-size:clamp(28px,4.5vw,40px);font-weight:700}
h2{font-size:12px;font-family:ui-monospace,Menlo,monospace;letter-spacing:.15em;
 text-transform:uppercase;color:var(--mut);font-weight:500;padding-bottom:9px;
 border-bottom:1px solid var(--line2);margin:0 0 20px}
h3{font-size:17px;font-weight:600;margin:26px 0 8px;font-family:ui-monospace,Menlo,monospace;
 letter-spacing:-.01em}
p{margin:0 0 13px;max-width:76ch}
code,.mono{font-family:ui-monospace,Menlo,monospace;font-size:.86em}
a{color:var(--amber)}
header.mast{padding:54px 0 28px;border-bottom:2px solid var(--ink);margin-bottom:34px}
.kick{font-family:ui-monospace,Menlo,monospace;font-size:11px;letter-spacing:.16em;
 text-transform:uppercase;color:var(--amber)}
section{margin-bottom:46px}
.tw{overflow-x:auto;border:1px solid var(--line);background:var(--pane);margin:0 0 16px}
table{border-collapse:collapse;width:100%;font-size:13px;min-width:760px}
th{text-align:left;font-family:ui-monospace,Menlo,monospace;font-size:10px;letter-spacing:.1em;
 text-transform:uppercase;color:var(--mut);font-weight:500;padding:10px 12px;background:var(--sunk);
 border-bottom:1px solid var(--line2);vertical-align:bottom;white-space:nowrap}
td{padding:9px 12px;border-bottom:1px solid var(--line);vertical-align:top;color:var(--ink2)}
tr:last-child td{border-bottom:none}
td strong{color:var(--ink)}
.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.pill{display:inline-block;font-family:ui-monospace,Menlo,monospace;font-size:9.5px;
 letter-spacing:.08em;text-transform:uppercase;padding:2px 6px;border:1px solid;font-weight:500;
 white-space:nowrap}
.p-own{color:var(--ok);border-color:var(--ok)}
.p-sup{color:var(--blue);border-color:var(--blue)}
.p-else{color:var(--stop);border-color:var(--stop)}
.p-mut{color:var(--mut);border-color:var(--line2)}
.aio{color:var(--amber);font-weight:600}
.stat{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1px;
 background:var(--line);border:1px solid var(--line);margin:0 0 32px}
.stat > div{background:var(--pane);padding:16px 18px}
.stat b{font-family:Sora,sans-serif;font-size:26px;font-weight:700;display:block;line-height:1;
 font-variant-numeric:tabular-nums}
.stat span{font-size:12.5px;color:var(--mut);display:block;margin-top:7px;line-height:1.4}
.warn{border:1px solid var(--line2);border-left:3px solid var(--stop);background:var(--pane);
 padding:15px 18px;margin:0 0 18px}
.warn .h{font-family:ui-monospace,Menlo,monospace;font-size:10px;letter-spacing:.12em;
 text-transform:uppercase;color:var(--stop);font-weight:600;margin-bottom:6px}
.note{border:1px solid var(--line2);border-left:3px solid var(--blue);background:var(--pane);
 padding:15px 18px;margin:0 0 18px}
.note .h{font-family:ui-monospace,Menlo,monospace;font-size:10px;letter-spacing:.12em;
 text-transform:uppercase;color:var(--blue);font-weight:600;margin-bottom:6px}
.foot{border-top:2px solid var(--ink);padding-top:18px;margin-top:50px;font-size:12.5px;
 color:var(--mut)}
